

class Location:
    def __init__(self, name, description):
        self.name = name
        self.description = description

room_zero = Location("antechamber", "With just a gentle push the door to the mansion swings open.\nThe ease of entry gives you little comfort, after all if it's this weasy to get in, why has nobody ever come out?\nYou find yourself standing in a dimly lit antechamber with three doors, to your right, your left and straight ahead.\nSudenly the door behind you slams shut. You pull at the handle but the door is imobile. Looks like you'll have to take one of the other doors.")

room_one = Location("small bedroom", "This is a small, but richly furnished, bedroom.\nAs you step inside the door behind you closes and locks.\nThere are three other doors leading out of the room.")

room_two = Location("large bedroom", "Judging by the size and furnishing, this room is the master bedroom.\nLayers of dust show it has been unused for quite some time.\nThe door behind you seals, leaving three exits from the room.")

room_three = Location("main hall", "Looking around you see a very large hall with a long banqueting table with places set for forty guests.\nThe table and settings are covered in dust and the two large fireplaces are cold and dark.\nThe door slams shut behinfd you, but there are three others leading out of the room.")

room_four = Location("kitchen", "It is an impressively large kitchen, but cold through lack of recent use. What foodstuffs remain onthe table and in the pots are badly decomposed.\nThe door behind you closes with a low creaking noise, leaving you three exits from the room.")

room_five = Location("study", "This small room contains comfortable chairs and a large desk.\nScattered accross the desk are dust covered papers that appear to be about hosehold expenses.\nA loud bang behind you startles you briefly before you realize it is the door slamming shut.\nThe room has three other exits.")

room_six = Location("library", "Rows upon rows of book line the walls of this high ceilinged room.\nYou have nevere seen so many books in your entire life, let alone in one place.\nAs the door locks itself behinfd you, you see three other doors leading out of the library.")

room_seven = Location("servants room", "This room is sparsely furnished with a small bed, chair and desk, all of which are of poor quality.\nAs the door behind you quietly closes and locks, you are struck by the stange layout of this mansion.\nEven this small servants room has three other exits.")

room_eight = Location("laboratory", "Various pieces of laboratory equipment cover tables and workbenches in this room.\nSome look ready for use, others are broken beyond repair.\nThe door behind you closes with a loud creaking sound, leaving you with three exits to the room.")

room_nine = Location("dining room", "There is a table and chairs to  seat six. The table is empty except for two candalebras.\nYou can see three doors leading out of the room and a fourth behind you that is closed and locked.")

room_ten = Location("conservatory", "Through the glass panes you can see the grounds of the mansion, but a faint glow from the glass convinces you that youo won't be able to break it.\nApart from one overgrown shub, the plants here have long since died.\nYou hear the door behind you obolt itself, but there are three other exits, thouogh curiously, none of them lead outside.")

room_eleven = Location("wine cellar", "You here some rats scurrying away as you enter the dark celler.\nIt remains well stocked with wine.\nThe door behind you shuts and bolts itseld, but looking around you can see three more doors.")

room_twelve = Location("attic", "Although roomy, the attic is dark with numerous spiderwebs criss-crossing amoung the myriad bric-a-brac that lies around.\nYou can make out three trapdoor exits, but you can find no trace of the door you entered the attic from.")

room_thirteen = Location("large bathroom", "Marble bathing features take up most of the room.\nIn one corner is a large fireplace with a big pot for heating water.\nThe door you entered through slams shut and you here the bolt slide in place.\nThere are three other doors in the room.")

room_fourteen = Location("family room", "It is comfortably decorated with chairs and small tables.\nSmall bookshelves line two of the walls.\nThe door behind you silently swings closed, but you see three other doors in the room.")

room_fifteen = Location("storage room", "Neatly stacked boxes occupy a large part of the room.\nLooking back you find that the door is no longer visible.\nHowever, there are three other doors that you can see.")

room_sixteen = Location("observatory", "The center of the domed room is taken up by a large telescope.\nThere are no exits to the roof, but there are three doorways other than the now sealed door you used to enter the obsevatory.")

room_seventeen = Location("small guest room", "The room has comfortable furnishing, all of which is covered in a thick layer of dust.\nYou feel a slight draft as the door behind you quietly closes. There are three other exits from the room.")

room_eighteen = Location("large pantry", "Food storage bins line the shelves of this room, but their contents have either rotted away, or lay coverd in dust.\nA clicking sound alerts you to the door behind you locking, but, strangely for a pantry, you see three other doors.")

room_nineteen = Location("large guest room", "A spacious, opulently furnished room with a bed , work desk adn comfortable  chairs.\nThe door behind you quietly closes, but you can see three others doors leading out of the room.")

room_twenty = Location("occult workshop", "The room is filled with the trappings of the sorcerers craft, tomes of arcane law, scrying pots, summoning circles and the like.\nThe door behind you closes with a thunderous boom, but you can make out three other doors leading from the room.")